'use strict';

// AGENT-3667: one honest enforcement summary per host (hard-stops yes/no, fails open/closed, evidence link),
// generated by scripts/host-gate-matrix.js from the same probes as the gate table, and published on the site.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const matrix = require('../scripts/host-gate-matrix');

const committed = JSON.parse(fs.readFileSync(matrix.RESULTS_PATH, 'utf8'));
const SUMMARY_PAGE = path.join(__dirname, '..', 'public', 'learn', 'enforcement-matrix.html');

test('every host has a summary row with hard-stops, fail mode and an evidence link', () => {
  assert.ok(Array.isArray(committed.summary), 'results.summary is missing');
  const ids = committed.summary.map((s) => s.id).sort();
  assert.deepEqual(ids, ['amp', 'claude-code', 'cline', 'codex', 'cursor', 'gemini-cli', 'opencode']);
  for (const s of committed.summary) {
    assert.ok(['yes', 'no', 'untested'].includes(s.hardStops), `${s.id}: hardStops ${s.hardStops}`);
    assert.ok(['closed', 'open', 'not applicable', 'untested'].includes(s.failMode), `${s.id}: failMode ${s.failMode}`);
    assert.match(s.evidence, /^https:\/\/github\.com\/IgorGanapolsky\/ThumbGate\/blob\/main\//, `${s.id}: evidence link`);
  }
});

test('the summary says what the probes recorded: Cursor fails closed, Claude Code fails open, Cline/OpenCode/Amp have no hook', () => {
  const by = Object.fromEntries(committed.summary.map((s) => [s.id, s]));
  assert.equal(by.cursor.hardStops, 'yes');
  assert.equal(by.cursor.failMode, 'closed');
  assert.equal(by['claude-code'].hardStops, 'yes');
  assert.equal(by['claude-code'].failMode, 'open');
  for (const id of ['cline', 'opencode', 'amp']) {
    assert.equal(by[id].hardStops, 'no', id);
    assert.equal(by[id].failMode, 'not applicable', id);
  }
  for (const id of ['codex', 'gemini-cli']) assert.equal(by[id].hardStops, 'untested', id);
});

test('a summary row that says "yes" with no enforced gate, or "closed" for an unrunnable host, fails validation', () => {
  const bad = JSON.parse(JSON.stringify(committed));
  for (const row of bad.rows) if (row.kind === 'gate') row.cells.cursor = { status: 'not enforced', check: 'x' };
  assert.ok(matrix.validateResults(bad).some((e) => /summary cursor: hardStops "yes" but no gate is enforced/.test(e)));
  const bad2 = JSON.parse(JSON.stringify(committed));
  bad2.summary.find((s) => s.id === 'amp').failMode = 'closed';
  assert.ok(matrix.validateResults(bad2).some((e) => /summary amp: failMode "closed" for a host with no runnable hook path/.test(e)));
});

test('the site page public/learn/enforcement-matrix.html equals a fresh render and carries the table', () => {
  const fresh = matrix.runProbes();
  const next = matrix.render(fresh, fs.readFileSync(matrix.README_PATH, 'utf8'));
  assert.equal(fs.readFileSync(SUMMARY_PAGE, 'utf8'), next.page, 'enforcement-matrix.html is stale: run npm run compat:matrix');
  const html = fs.readFileSync(SUMMARY_PAGE, 'utf8');
  assert.match(html, /Fails (open|closed)/i);
  assert.match(html, /no hook/i);
});
